# Renderers for the generated files. Each takes the binding model and returns
# the whole file as one CRLF-joined string. There is no timestamp anywhere:
# generation is deterministic, so CI can compare a fresh run with the committed
# files byte for byte.

function ConvertTo-RelayInclude {
    <#
    .SYNOPSIS
        Renders relay/bindings.generated.ahk.
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param([Parameter(Mandatory)]$Model)

    $nl = $script:Crlf
    $ahk = [System.Collections.Generic.List[string]]::new()
    $ahk.Add('; Generated by tools/generate.ps1 from config/bindings.json. Do not edit.')
    $ahk.Add(";   chord set: $($Model.ActiveChordSet)")
    $ahk.Add('')
    $ahk.Add("BINDINGS_SOURCE_HASH := `"$($Model.SourceHash)`"")
    $ahk.Add('')
    $ahk.Add('TIMING := Map(')
    $ahk.Add("    `"repeatWindowMs`", $($Model.Timing.RepeatWindowMs),")
    $ahk.Add("    `"layerTimeoutMs`", $($Model.Timing.LayerTimeoutMs))")
    $ahk.Add('')
    $ahk.Add('RELAY := Map(')
    $ahk.Add("    `"runHidden`", $(ConvertTo-AhkBool -Value $Model.Relay.RunHidden),")
    $ahk.Add("    `"logFile`",   `"$(ConvertTo-AhkString -Value (ConvertTo-EmittedPath -Relative $Model.Relay.LogFile))`",")
    $ahk.Add("    `"linksFile`", `"$(ConvertTo-AhkString -Value (ConvertTo-EmittedPath -Relative $Model.Relay.LinksFile))`")")
    $ahk.Add('')
    $ahk.Add('SCREENSHOT := Map(')
    $ahk.Add("    `"script`",    `"$(ConvertTo-AhkString -Value (ConvertTo-EmittedPath -Relative $Model.Screenshot.Script))`",")
    $ahk.Add("    `"format`",    `"$(ConvertTo-AhkString -Value $Model.Screenshot.Format)`",")
    $ahk.Add("    `"saveDir`",   `"$(ConvertTo-AhkString -Value $Model.Screenshot.SaveDir)`",")
    $ahk.Add("    `"clipboard`", $(ConvertTo-AhkBool -Value $Model.Screenshot.Clipboard))")
    $ahk.Add('')
    $ahk.Add('TURN := Map(')
    $ahk.Add("    `"counts`",      $($Model.Turn.Counts),")
    $ahk.Add("    `"steps`",       $($Model.Turn.Steps),")
    $ahk.Add("    `"stepDelayMs`", $($Model.Turn.StepDelayMs))")
    $ahk.Add('')
    $ahk.Add('ACTIONS := Map(')

    $actionBlocks = foreach ($action in $Model.Actions.Values) {
        $fields = [System.Collections.Generic.List[string]]::new()
        $fields.Add("        `"kind`",  `"$(ConvertTo-AhkString -Value $action.Kind)`"")
        $fields.Add("        `"label`", `"$(ConvertTo-AhkString -Value $action.Label)`"")
        switch ($action.Kind) {
            'openUrl' {
                $fields.Add("        `"url`",   `"$(ConvertTo-AhkString -Value $action.Url)`"")
                $fields.Add("        `"local`", $(ConvertTo-AhkBool -Value $action.Local)")
            }
            'launch' {
                $targets = ($action.Targets | ForEach-Object { "`"$(ConvertTo-AhkString -Value $_)`"" }) -join ', '
                $fields.Add("        `"targets`", [$targets]")
            }
            'layer' {
                foreach ($direction in $script:Directions) {
                    $fields.Add("        `"$direction`", `"$(ConvertTo-AhkString -Value $action.Layer[$direction])`"")
                }
            }
        }
        "    `"$(ConvertTo-AhkString -Value $action.Id)`", Map($nl" + ($fields -join ",$nl") + ')'
    }
    $ahk.Add(($actionBlocks -join ",$nl"))
    $ahk.Add(')')
    $ahk.Add('')
    $ahk.Add('BINDINGS := Map(')

    $bindingBlocks = foreach ($chord in $Model.Chords) {
        $lines = @(
            "    `"$(ConvertTo-AhkString -Value $chord.Hotkey)`", Map("
            "        `"id`",       `"$(ConvertTo-AhkString -Value $chord.Id)`","
            "        `"hotkey`",   `"$(ConvertTo-AhkString -Value $chord.Hotkey)`","
            "        `"upHotkey`", `"$(ConvertTo-AhkString -Value $chord.UpHotkey)`","
            "        `"display`",  `"$(ConvertTo-AhkString -Value $chord.Display)`","
            "        `"key`",      `"$(ConvertTo-AhkString -Value $chord.Key)`","
            "        `"modsDown`", `"$(ConvertTo-AhkString -Value $chord.ModsDown)`","
            "        `"modsUp`",   `"$(ConvertTo-AhkString -Value $chord.ModsUp)`","
            "        `"where`",    `"$(ConvertTo-AhkString -Value $chord.Where)`")"
        )
        $lines -join $nl
    }
    $ahk.Add(($bindingBlocks -join ",$nl"))
    $ahk.Add(')')
    $ahk.Add('')
    return ($ahk -join $nl)
}

function ConvertTo-LinksExample {
    <#
    .SYNOPSIS
        Renders config/links.local.example.json, the template for the
        gitignored overlay of real contest URLs.
    .DESCRIPTION
        Every URL here passed the model's URL check, which bans quotes and
        backslashes, so none needs JSON escaping.
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param([Parameter(Mandatory)]$Model)

    $nl = $script:Crlf
    $json = [System.Collections.Generic.List[string]]::new()
    $json.Add('{')
    $json.Add('  "_comment": "Generated by tools/generate.ps1. Copy to config/links.local.json (gitignored) and replace each placeholder with the real URL. Note that browser is optional: the full path of the browser linked to the Contest Management profile, so that a link does not move focus to another browser.",')
    # Joined rather than appended, so no entry is left with a trailing comma
    # when there are no local links.
    $entries = @('  "browser": ""') + @($Model.LocalLinkIds | ForEach-Object { "  `"$_`": `"$($Model.Actions[$_].Url)`"" })
    $json.Add(($entries -join ",$nl"))
    $json.Add('}')
    $json.Add('')
    return ($json -join $nl)
}

function ConvertTo-EntrySheet {
    <#
    .SYNOPSIS
        Renders docs/control-panel-entry-sheet.md: what to program on every
        button of every profile.
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param([Parameter(Mandatory)]$Model)

    $lines = @(
        Get-SheetIntro -Model $Model
        Get-SheetProfileSection -Model $Model
        Get-SheetLayerSection -Model $Model
        Get-SheetStepSection -Model $Model
        Get-SheetTurnSection -Model $Model
        Get-SheetLinkSection
        Get-SheetTroubleshootingSection
    )
    return ($lines -join $script:Crlf)
}
